alter table public.expense_budgets drop constraint if exists expense_budgets_unique_category_period;
alter table public.expense_budgets add constraint expense_budgets_unique_taxonomy_period unique (user_id,category_id,subcategory_id,start_date,end_date);
drop function if exists public.expense_manager_budget_progress();
create function public.expense_manager_budget_progress() returns table(id uuid,category_id uuid,subcategory_id uuid,category_name text,subcategory_name text,category_icon text,category_color text,category_archived boolean,budget_amount numeric,period text,start_date date,end_date date,spent numeric) language sql security invoker stable set search_path=public as $$ select b.id,b.category_id,b.subcategory_id,c.name,s.name,c.icon,c.color,c.is_archived,b.amount,b.period,b.start_date,b.end_date,coalesce(sum(t.amount),0)::numeric from public.expense_budgets b join public.expense_categories c on c.id=b.category_id and c.user_id=b.user_id left join public.expense_subcategories s on s.id=b.subcategory_id and s.user_id=b.user_id left join public.expense_transactions t on t.user_id=b.user_id and t.category_id=b.category_id and (b.subcategory_id is null or t.subcategory_id=b.subcategory_id) and t.type='expense' and t.date between b.start_date and b.end_date where b.user_id=(select auth.uid()) group by b.id,b.category_id,b.subcategory_id,c.name,s.name,c.icon,c.color,c.is_archived,b.amount,b.period,b.start_date,b.end_date order by b.start_date desc,c.name asc,s.name asc; $$;
grant execute on function public.expense_manager_budget_progress() to authenticated;